import{_ as e,o as i,c as o,a2 as s}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Estrutura Social e Mobilidade de Classes","description":"","frontmatter":{},"headers":[],"relativePath":"pt/0036-社会结构与阶层流动.md","filePath":"pt/0036-社会结构与阶层流动.md"}'),d={name:"pt/0036-社会结构与阶层流动.md"};function t(r,a,n,c,l,m){return i(),o("div",null,[...a[0]||(a[0]=[s('<h1 id="estrutura-social-e-mobilidade-de-classes" tabindex="-1">Estrutura Social e Mobilidade de Classes <a class="header-anchor" href="#estrutura-social-e-mobilidade-de-classes" aria-label="Permalink to &quot;Estrutura Social e Mobilidade de Classes&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projeto</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do documento</td><td>36</td></tr><tr><td>Módulo</td><td>Tipologia de Civilização e Sistema Social</td></tr><tr><td>Palavras-chave principais</td><td>Estrutura Social, Mobilidade de Classes, Sistema Aberto, Promoção Justa, Anti-Estagnação</td></tr></tbody></table><h2 id="i-conceitos-basicos-de-estrutura-social-e-a-busca-da-civilizacao-simbiotica" tabindex="-1">I. Conceitos Básicos de Estrutura Social e a Busca da Civilização Simbiótica <a class="header-anchor" href="#i-conceitos-basicos-de-estrutura-social-e-a-busca-da-civilizacao-simbiotica" aria-label="Permalink to &quot;I. Conceitos Básicos de Estrutura Social e a Busca da Civilização Simbiótica&quot;">​</a></h2><p>Estrutura social refere-se ao modo de organização e ao padrão de relações entre diferentes grupos em uma sociedade, incluindo múltiplas dimensões como divisão de classes, divisão de papéis, distribuição de poder, alocação de recursos, etc. Em qualquer forma de civilização, a estrutura social influencia profundamente as oportunidades de desenvolvimento dos indivíduos, a eficiência operacional da sociedade e a estabilidade de longo prazo da civilização.</p><p>Na era do sistema de cultivo predatório, a estrutura social apresentava extrema estagnação e desigualdade: existia um abismo intransponível entre os fortes e os fracos, a origem determinava o destino, e os seres da base quase não tinham possibilidade de mobilidade ascendente. Essa estrutura social estagnada não apenas causou sofrimento infinito, mas também levou à perda de vitalidade social e à estagnação da civilização — o potencial da grande maioria dos indivíduos foi desperdiçado, e poucos privilegiados, para manter seus privilégios, não hesitaram em suprimir a inovação e o progresso.</p><p>Após o estabelecimento da civilização simbiótica de âncoras, a construção de uma estrutura social &quot;aberta, fluida, justa e vital&quot; foi considerada um dos objetivos centrais. A civilização simbiótica acredita firmemente: uma estrutura social saudável deve permitir que cada indivíduo mude seu destino por meio de seu próprio esforço, deve permitir que os recursos sociais fluam para as pessoas mais capazes e mais contribuintes, e deve manter canais de mobilidade fluidos entre diferentes classes. Somente assim, a iniciativa e a criatividade de todos os seres simbióticos podem ser plenamente despertadas, e o grande objetivo do progresso comum de todas as raças pode ser实现.</p><p>A busca central da estrutura social da civilização simbiótica pode ser resumida em quatro frases:</p><ol><li><strong>Abertura e Inclusão</strong>: A sociedade está aberta a todos os indivíduos, não estabelecendo barreiras de acesso por fatores como raça, origem, gênero, etc.</li><li><strong>Mobilidade Fluida</strong>: Canais de mobilidade fluidos são mantidos entre diferentes classes, e os indivíduos podem实现 mobilidade ascendente por meio de esforço</li><li><strong>Justiça e Equidade</strong>: A alocação de recursos e a oferta de oportunidades seguem princípios de justiça, e cada indivíduo tem oportunidades iguais de desenvolvimento</li><li><strong>Plena de Vitalidade</strong>: A estrutura social pode despertar a iniciativa e a criatividade dos indivíduos, mantendo abundante vitalidade de desenvolvimento</li></ol><h2 id="ii-divisao-de-classes-sociais-da-civilizacao-simbiotica" tabindex="-1">II. Divisão de Classes Sociais da Civilização Simbiótica <a class="header-anchor" href="#ii-divisao-de-classes-sociais-da-civilizacao-simbiotica" aria-label="Permalink to &quot;II. Divisão de Classes Sociais da Civilização Simbiótica&quot;">​</a></h2><p>A divisão de classes sociais da civilização simbiótica não toma origem, raça ou riqueza como critérios, mas sim o &quot;grau de simbiose&quot; e o &quot;reino de cultivo&quot; como referências centrais, formando um sistema de classes dinâmico e aberto:</p><table tabindex="0"><thead><tr><th>Classe</th><th>Nome</th><th>Proporção</th><th>Características centrais</th><th>Principais responsabilidades</th></tr></thead><tbody><tr><td>Primeira camada</td><td>Líderes simbióticos</td><td>Cerca de 1%</td><td>Fortes supremos de plano, grau de simbiose nível S, líderes centrais da civilização</td><td>Decisão estratégica, manutenção de leis, governança entre planos</td></tr><tr><td>Segunda camada</td><td>Ossos simbióticos</td><td>Cerca de 5%</td><td>Cultivadores avançados, grau de simbiose nível A, força central de todas as áreas</td><td>Pesquisa e desenvolvimento tecnológico, gestão organizacional, formação de talentos</td></tr><tr><td>Terceira camada</td><td>Profissionais simbióticos</td><td>Cerca de 20%</td><td>Cultivadores intermediários, grau de simbiose nível B, talentos profissionais de todas as indústrias</td><td>Serviços profissionais, aplicação tecnológica, gestão de base</td></tr><tr><td>Quarta camada</td><td>Massas simbióticas</td><td>Cerca de 60%</td><td>Cultivadores iniciantes, grau de simbiose nível C, força básica da civilização</td><td>Cultivo básico, serviços de produção, participação comunitária</td></tr><tr><td>Quinta camada</td><td>Novatos simbióticos</td><td>Cerca de 14%</td><td>Recém-chegados ou candidatos a melhoria, grau de simbiose nível D, precisam de ajuda e orientação</td><td>Aprendizado e crescimento, aceitação de orientação, integração gradual</td></tr></tbody></table><p>É necessário enfatizar especialmente que essa divisão de classes não é fixa, mas dinâmica e fluida. Cada indivíduo pode melhorar seu grau de simbiose e reino de cultivo por meio de seu próprio esforço,实现ando a ascensão de classe; por outro lado, se o indivíduo não buscar progresso ou até violar a ética simbiótica, também pode ocorrer a queda de classe.</p><p>Além disso, a divisão de classes não significa privilégio e discriminação. Os indivíduos de cada classe desfrutam de direitos básicos iguais e dignidade pessoal igual, e as diferenças de classe refletem-se principalmente na divisão de responsabilidades e na alocação de recursos, não na superioridade ou inferioridade pessoal.</p><h2 id="iii-mecanismos-e-canais-de-mobilidade-de-classes" tabindex="-1">III. Mecanismos e Canais de Mobilidade de Classes <a class="header-anchor" href="#iii-mecanismos-e-canais-de-mobilidade-de-classes" aria-label="Permalink to &quot;III. Mecanismos e Canais de Mobilidade de Classes&quot;">​</a></h2><p>A civilização simbiótica estabeleceu mecanismos de mobilidade de classes de múltiplos canais e múltiplos níveis, garantindo que cada indivíduo tenha a oportunidade de实现 mobilidade ascendente por meio de seu próprio esforço:</p><h3 id="_3-1-canal-de-promocao-por-cultivo" tabindex="-1">3.1 Canal de Promoção por Cultivo <a class="header-anchor" href="#_3-1-canal-de-promocao-por-cultivo" aria-label="Permalink to &quot;3.1 Canal de Promoção por Cultivo&quot;">​</a></h3><p>A promoção por cultivo é o canal mais importante de mobilidade de classes. Por meio da abertura dos trezentos sistemas de cultivo de origem, a civilização simbiótica fornece a cada indivíduo um caminho claro de promoção por cultivo:</p><ul><li><strong>Promoção de reino</strong>: O cultivador melhora seu reino por meio do cultivo, do iniciante ao intermediário, avançado e supremo, e cada avanço de reino pode trazer a ascensão de classe</li><li><strong>Avanço de sistema</strong>: O cultivador que obtém resultados de avanço em um determinado sistema de cultivo pode获得 melhoria do grau de simbiose e ascensão de classe</li><li><strong>Inovação tecnológica</strong>: O cultivador que obtém resultados de inovação em tecnologias de cultivo, tecnologias de engenharia, etc., pode获得 honras e recompensas de recursos, impulsionando a ascensão de classe</li></ul><p>O princípio central do canal de promoção por cultivo é &quot;todos têm um caminho&quot; — independentemente da origem, desde que se esforce no cultivo, há oportunidade de实现 ascensão de classe.</p><h3 id="_3-2-canal-de-promocao-por-contribuicao" tabindex="-1">3.2 Canal de Promoção por Contribuição <a class="header-anchor" href="#_3-2-canal-de-promocao-por-contribuicao" aria-label="Permalink to &quot;3.2 Canal de Promoção por Contribuição&quot;">​</a></h3><p>Além do reino de cultivo, a contribuição para a civilização simbiótica também é uma base importante para a mobilidade de classes:</p><ul><li><strong>Contribuição de serviços públicos</strong>: Participar de serviços públicos como manutenção de âncoras, orientação de mentores, resgate de emergência, etc., acumulando valores de contribuição</li><li><strong>Contribuição de pesquisa e desenvolvimento tecnológico</strong>: Fazer contribuições de pesquisa e desenvolvimento em áreas como tecnologias de cultivo, tecnologias de engenharia, etc.</li><li><strong>Contribuição de disseminação cultural</strong>: Disseminar a filosofia simbiótica, criar obras culturais, promover intercâmbios civilizacionais</li><li><strong>Contribuição de participação na governança</strong>: Participar da governança social, propor sugestões de políticas, promover a otimização de sistemas</li></ul><p>O princípio central do canal de promoção por contribuição é &quot;mais trabalho, mais ganho&quot; — quanto maior a contribuição para a civilização simbiótica, mais recompensas e melhorias de classe são obtidas.</p><h3 id="_3-3-canal-de-promocao-por-educacao" tabindex="-1">3.3 Canal de Promoção por Educação <a class="header-anchor" href="#_3-3-canal-de-promocao-por-educacao" aria-label="Permalink to &quot;3.3 Canal de Promoção por Educação&quot;">​</a></h3><p>A educação é uma escada importante para a mobilidade de classes. A civilização simbiótica estabeleceu um sistema completo de promoção educacional:</p><ul><li><strong>Educação básica</strong>: Fornecer educação básica de cultivo gratuita a cada indivíduo, garantindo a equidade do ponto de partida</li><li><strong>Educação avançada</strong>: Selecionar alunos excelentes por meio de exames para ingressar em faculdades avançadas de cultivo, recebendo treinamento de nível mais alto</li><li><strong>Educação de elite</strong>: Selecionar os indivíduos mais promissores para ingressar no plano de formação de elite, recebendo suporte de recursos de ponta</li><li><strong>Educação ao longo da vida</strong>: Fornecer oportunidades de aprendizado e melhoria contínuos a indivíduos de todas as idades</li></ul><p>O princípio central do canal de promoção por educação é &quot;igualdade de oportunidades&quot; — cada indivíduo tem oportunidades iguais de实现 ascensão de classe por meio da educação.</p><h3 id="_3-4-canal-de-promocao-especial" tabindex="-1">3.4 Canal de Promoção Especial <a class="header-anchor" href="#_3-4-canal-de-promocao-especial" aria-label="Permalink to &quot;3.4 Canal de Promoção Especial&quot;">​</a></h3><p>Para indivíduos que fazem contribuições especiais ou demonstram talentos especiais em áreas especiais, a civilização simbiótica possui canais de promoção especiais:</p><ul><li><strong>Promoção excepcional de talentos especiais</strong>: Para indivíduos com talentos especiais ou que fazem contribuições especiais em uma determinada área, pode-se promover a classe excepcionalmente</li><li><strong>Promoção por mérito em eventos de emergência</strong>: Indivíduos que fazem méritos no enfrentamento de eventos de emergência (como desastres, invasões, crises, etc.) podem receber promoção rápida</li><li><strong>Promoção por contribuição à exploração entre planos</strong>: Indivíduos que fazem contribuições proeminentes na exploração e arqueologia entre planos podem receber promoção</li></ul><h2 id="iv-garantias-institucionais-para-prevenir-a-estagnacao-de-classes" tabindex="-1">IV. Garantias Institucionais para Prevenir a Estagnação de Classes <a class="header-anchor" href="#iv-garantias-institucionais-para-prevenir-a-estagnacao-de-classes" aria-label="Permalink to &quot;IV. Garantias Institucionais para Prevenir a Estagnação de Classes&quot;">​</a></h2><p>A fluidez da mobilidade de classes requer garantias institucionais. A civilização simbiótica estabeleceu os seguintes sistemas para prevenir a estagnação de classes:</p><h3 id="_4-1-sistema-antimonopolio" tabindex="-1">4.1 Sistema Antimonopólio <a class="header-anchor" href="#_4-1-sistema-antimonopolio" aria-label="Permalink to &quot;4.1 Sistema Antimonopólio&quot;">​</a></h3><p>A Constituição Simbiótica e a Lei Antimonopólio proíbem explicitamente qualquer organização ou indivíduo de monopolizar recursos de cultivo, sistemas de cultivo, oportunidades educacionais, etc. O sistema antimonopólio impede que grupos de interesses consolidem seus privilégios por meio do monopólio de recursos, garantindo a abertura e a fluidez dos recursos.</p><h3 id="_4-2-sistema-de-imposto-sobre-herancas-e-doacoes" tabindex="-1">4.2 Sistema de Imposto sobre Heranças e Doações <a class="header-anchor" href="#_4-2-sistema-de-imposto-sobre-herancas-e-doacoes" aria-label="Permalink to &quot;4.2 Sistema de Imposto sobre Heranças e Doações&quot;">​</a></h3><p>Para impedir que a riqueza e os recursos causem estagnação de classes por meio da transmissão intergeracional, a civilização simbiótica implementa um sistema progressivo de imposto sobre heranças e doações. Heranças e doações de alto valor líquido exigem o pagamento de uma proporção relativamente alta de impostos, que são incorporados ao pool de recursos públicos e usados para o interesse comum de todos os seres simbióticos.</p><h3 id="_4-3-sistema-de-equidade-educacional" tabindex="-1">4.3 Sistema de Equidade Educacional <a class="header-anchor" href="#_4-3-sistema-de-equidade-educacional" aria-label="Permalink to &quot;4.3 Sistema de Equidade Educacional&quot;">​</a></h3><p>A civilização simbiótica garante a equidade educacional por meio da Lei de Garantia Educacional:</p><ul><li>A educação básica está aberta gratuitamente a todos os cidadãos</li><li>A seleção para educação avançada e educação de elite toma capacidade e potencial como critérios, não origem e riqueza</li><li>Fornecer suporte educacional adicional e compensação para grupos vulneráveis</li><li>Proibir qualquer forma de discriminação educacional e privilégio educacional</li></ul><h3 id="_4-4-sistema-de-monitoramento-da-mobilidade-de-classes" tabindex="-1">4.4 Sistema de Monitoramento da Mobilidade de Classes <a class="header-anchor" href="#_4-4-sistema-de-monitoramento-da-mobilidade-de-classes" aria-label="Permalink to &quot;4.4 Sistema de Monitoramento da Mobilidade de Classes&quot;">​</a></h3><p>O núcleo de informações da rede simbiótica monitora em tempo real a situação da mobilidade das classes sociais, e os indicadores centrais de monitoramento incluem:</p><ul><li><strong>Taxa de mobilidade intergeracional</strong>: O grau de diferença entre a classe da prole e a classe dos pais</li><li><strong>Taxa de mobilidade ascendente</strong>: A proporção de indivíduos que实现am ascensão de classe em cada ciclo</li><li><strong>Taxa de mobilidade descendente</strong>: A proporção de indivíduos que experimentam queda de classe em cada ciclo</li><li><strong>Índice de estagnação de classes</strong>: O grau de &quot;hereditariedade&quot; dentro de cada classe</li></ul><p>Quando os indicadores de monitoramento mostram que a mobilidade de classes apresenta obstrução ou tendência de estagnação, as instituições de governança adotam prontamente ajustes de políticas, garantindo a fluidez da mobilidade de classes.</p><h2 id="v-diferencas-de-estrutura-social-entre-os-cinco-tipos-de-civilizacao" tabindex="-1">V. Diferenças de Estrutura Social entre os Cinco Tipos de Civilização <a class="header-anchor" href="#v-diferencas-de-estrutura-social-entre-os-cinco-tipos-de-civilizacao" aria-label="Permalink to &quot;V. Diferenças de Estrutura Social entre os Cinco Tipos de Civilização&quot;">​</a></h2><p>Os cinco tipos de civilização simbiótica têm suas próprias características na estrutura social:</p><table tabindex="0"><thead><tr><th>Tipo</th><th>Características da estrutura social</th><th>Características da mobilidade de classes</th></tr></thead><tbody><tr><td>Intensivo do Leste Asiático</td><td>Orientado coletivamente, hierarquia clara, baseado em clãs e seitas</td><td>Canais de mobilidade baseados principalmente na promoção de seitas, velocidade de mobilidade média</td></tr><tr><td>de Bem-estar Nórdico</td><td>Plano, alta igualdade, classes fracas</td><td>Pequena diferença de classes, baixa pressão de mobilidade, velocidade de mobilidade mais lenta</td></tr><tr><td>Pluralístico da América do Norte</td><td>Mercantilizado, pluralístico, competição acirrada</td><td>Canais de mobilidade baseados principalmente na competição de mercado, velocidade de mobilidade rápida, mas grande diferença</td></tr><tr><td>Social da Europa Continental</td><td>Corporativismo, cogestão trabalho-capital, democracia deliberativa</td><td>Canais de mobilidade baseados principalmente em qualificações profissionais e negociação coletiva, mobilidade estável</td></tr><tr><td>de Desenvolvimento e Ultrapassagem</td><td>Governo forte, mobilidade rápida, desenvolvimento gradiente</td><td>Velocidade de mobilidade rápida, muitas oportunidades de ascensão, abundante vitalidade social</td></tr></tbody></table><p>Embora existam diferenças na estrutura social de cada tipo, todos seguem os princípios básicos da Constituição Simbiótica e estão comprometidos em construir uma estrutura social aberta, fluida, justa e vital.</p><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>A estrutura social e a mobilidade de classes são um dos temas centrais da construção institucional da civilização simbiótica de âncoras. Por meio da divisão dinâmica de classes centrada no grau de simbiose e no reino de cultivo, dos mecanismos de mobilidade de classes de múltiplos canais e das garantias institucionais para prevenir a estagnação de classes, a civilização simbiótica construiu uma estrutura social aberta, fluida, justa e vital. Nessa estrutura social, cada indivíduo pode mudar seu destino por meio de seu próprio esforço, os recursos sociais podem fluir para as pessoas mais capazes e mais contribuintes, e toda a civilização mantém abundante vitalidade de desenvolvimento. Essa é precisamente a importante base social que permite à civilização simbiótica实现ar o progresso comum de todas as raças.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos relacionados&quot;">​</a></h2><ul><li>26-个体与集体平衡原理 (Princípio do Equilíbrio entre Indivíduo e Coletivo)</li><li>29-共生度评估体系 (Sistema de Avaliação do Grau de Simbiose)</li><li>30-五种共生文明分型总览 (Visão Geral dos Cinco Tipos de Civilização Simbiótica)</li></ul>',51)])])}const b=e(d,[["render",t]]);export{p as __pageData,b as default};
